import{_ as t,o as a,c as i,a2 as r}from"./chunks/framework.5akMI7mQ.js";const m=JSON.parse('{"title":"Security","description":"","frontmatter":{},"headers":[],"relativePath":"SECURITY.md","filePath":"SECURITY.md","lastUpdated":1791201732000}'),s={name:"SECURITY.md"};function o(n,e,l,d,c,u){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h1><h2 id="reporting" tabindex="-1">Reporting <a class="header-anchor" href="#reporting" aria-label="Permalink to &quot;Reporting&quot;">​</a></h2><p>Do not publish exploit details, credentials, or malicious artifacts in public issues. Use GitHub&#39;s private vulnerability reporting for <a href="https://github.com/wednesdev-id/wednesdev-serverless-engine/security/advisories/new" target="_blank" rel="noreferrer">wednesdev-id/wednesdev-serverless-engine</a> if enabled. If unavailable, open a public issue requesting a private contact <strong>without vulnerability details</strong>. No response-time or supported-release guarantee is currently offered; project is alpha.</p><p>Include affected revision, OS/architecture, Wasmtime version, bounded reproduction, impact, and whether the same daemon PID survives. Coordinate disclosure before posting details.</p><h2 id="trust-model" tabindex="-1">Trust model <a class="header-anchor" href="#trust-model" aria-label="Permalink to &quot;Trust model&quot;">​</a></h2><p>Guest WASM is untrusted; the operator, host OS, daemon binary, build toolchain, adapter, registry, and artifact directory are trusted. Typed ABI validation is necessary but does not make arbitrary guest code safe. Wasmtime isolation is not a guarantee against runtime vulnerabilities or all resource exhaustion.</p><p>Guests receive no host filesystem preopens, inherited environment/secrets, or outbound HTTP capability by default. They cannot invoke arbitrary host executables or access host devices through exposed APIs. Capability enablement is not generally implemented: unsupported manifest fields/requests must be rejected, not treated as policy enforcement. Clock/logging configuration is unsupported; do not assume a total absence of nondeterministic WASI facilities.</p><p>Per-invocation memory limits and epoch deadlines bound specific guest resources, not total daemon RSS or wall-clock request duration. Global/per-function admission rejects saturation with 429; it is not authentication, abuse prevention, or a host resource budget. Compilation, response copies, HTTP buffering, caches, and runtime bugs can still exhaust host resources.</p><h2 id="operator-precautions" tabindex="-1">Operator precautions <a class="header-anchor" href="#operator-precautions" aria-label="Permalink to &quot;Operator precautions&quot;">​</a></h2><ul><li>Bind to localhost by default. Before public exposure, use an authenticated TLS reverse proxy with request-size limits, timeouts, and rate limits.</li><li>Run as an unprivileged user with OS resource limits and no unnecessary secrets. Keep Wasmtime and dependencies patched.</li><li>Keep registry and artifacts writable only by trusted operators. Never deserialize attacker-controlled native compiled artifacts.</li><li>Serialize deploy writers. Registry rename does not atomically publish artifact contents, prevent symlink substitution, or provide multi-writer transactions.</li><li>Enforce client-side deadlines and test same-process recovery after loops, memory exhaustion, malformed artifacts, and traps.</li><li>Verify adapter download checksum in <code>scripts/build-fixtures.sh</code>; review dependency/tool upgrades before adopting them.</li></ul><p>No persistent deploy compilation cache exists. Do not interpret deploy-time compilation as a guarantee that restart avoids compilation, or treat successful smoke tests as full V0 acceptance.</p>',11)])])}const h=t(s,[["render",o]]);export{m as __pageData,h as default};
